#define MAXN 205

static int n, m;
static char g[MAXN][MAXN];
static char pathbuf[MAXN * MAXN];

typedef struct {
    char *s;
    int len;
} Cand;

static Cand *arr = NULL;
static int arr_sz = 0, arr_cap = 0;

static const int dx[8] = {-1,-1,-1,0,0,1,1,1};
static const int dy[8] = {-1,0,1,-1,1,-1,0,1};

static void add_candidate(const char *s, int len) {
    if (len <= 0) return;
    if (arr_sz == arr_cap) {
        arr_cap = arr_cap ? arr_cap * 2 : 1024;
        arr = (Cand*)realloc(arr, arr_cap * sizeof(Cand));
    }
    arr[arr_sz].s = (char*)malloc((len + 1) * sizeof(char));
    memcpy(arr[arr_sz].s, s, len);
    arr[arr_sz].s[len] = '\0';
    arr[arr_sz].len = len;
    arr_sz++;
}

static int cmp_cand(const void *a, const void *b) {
    const Cand *x = (const Cand*)a;
    const Cand *y = (const Cand*)b;
    if (x->len != y->len) return y->len - x->len;   // longer first
    return strcmp(x->s, y->s);                      // lexicographically smaller first
}

static int lcp(const char *a, const char *b) {
    int i = 0;
    while (a[i] && b[i] && a[i] == b[i]) i++;
    return i;
}

int main(void) {
    if (scanf("%d %d", &n, &m) != 2) return 0;
    for (int i = 0; i < n; i++) {
        scanf("%s", g[i]);
    }

    /* Build all line strings in 8 directions on torus */
    for (int x = 0; x < n; x++) {
        for (int y = 0; y < m; y++) {
            for (int d = 0; d < 8; d++) {
                int px = x, py = y;
                for (int k = 0; k < n * m; k++) {
                    pathbuf[k] = g[px][py];
                    px = (px + dx[d] + n) % n;
                    py = (py + dy[d] + m) % m;
                }
                pathbuf[n * m] = '\0';
                add_candidate(pathbuf, n * m);
            }
        }
    }

    qsort(arr, arr_sz, sizeof(Cand), cmp_cand);

    int bestLen = 0;
    char *best = NULL;

    for (int i = 0; i < arr_sz; ) {
        int j = i + 1;
        while (j < arr_sz && strcmp(arr[i].s, arr[j].s) == 0) j++;

        /* Exact duplicate whole path => valid */
        if (j - i >= 2) {
            if (arr[i].len > bestLen || (arr[i].len == bestLen && (!best || strcmp(arr[i].s, best) < 0))) {
                bestLen = arr[i].len;
                best = arr[i].s;
            }
        }

        /* Compare with next different strings for common prefixes */
        if (j < arr_sz) {
            int common = lcp(arr[i].s, arr[j].s);
            if (common > bestLen) {
                bestLen = common;
                best = arr[i].s;
            } else if (common == bestLen && common > 0) {
                char tmp1[MAXN * MAXN], tmp2[MAXN * MAXN];
                memcpy(tmp1, arr[i].s, common);
                tmp1[common] = '\0';
                if (!best || strcmp(tmp1, best) < 0) {
                    best = (char*)malloc(common + 1);
                    memcpy(best, tmp1, common + 1);
                }
            }
        }

        i = j;
    }

    if (bestLen == 0) {
        printf("0\n");
    } else {
        char out[MAXN * MAXN];
        memcpy(out, best, bestLen);
        out[bestLen] = '\0';
        printf("%s\n", out);
    }

    for (int i = 0; i < arr_sz; i++) free(arr[i].s);
    free(arr);
    return 0;
}

