import java.util.*;

public class MagicSpell {
    static int n, m;
    static char[][] grid;
    static int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    static int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        grid = new char[n][m];
        for (int i = 0; i < n; i++) {
            String s = sc.next();
            for (int j = 0; j < m; j++) {
                grid[i][j] = s.charAt(j);
            }
        }
        sc.close();

        Map<String, List<int[]>> map = new HashMap<>();

        // Build extended grid for wrapping
        int extN = 3 * n;
        int extM = 3 * m;
        char[][] ext = new char[extN][extM];
        for (int i = 0; i < extN; i++) {
            for (int j = 0; j < extM; j++) {
                ext[i][j] = grid[i % n][j % m];
            }
        }

        // Collect all strings starting in central copy
        for (int i = n; i < 2 * n; i++) {
            for (int j = m; j < 2 * m; j++) {
                for (int d = 0; d < 8; d++) {
                    StringBuilder sb = new StringBuilder();
                    int r = i, c = j;
                    for (int len = 0; len < Math.max(n, m); len++) {
                        sb.append(ext[r][c]);
                        String s = sb.toString();
                        if (s.length() >= 2) {
                            map.computeIfAbsent(s, k -> new ArrayList<>()).add(new int[]{i - n, j - m, d, len + 1});
                        }
                        r += dr[d];
                        c += dc[d];
                        if (r < 0 || r >= extN || c < 0 || c >= extM) break;
                    }
                }
            }
        }

        String best = "";
        for (Map.Entry<String, List<int[]>> entry : map.entrySet()) {
            String s = entry.getKey();
            List<int[]> positions = entry.getValue();
            if (canPlaceNonOverlapping(positions, s.length())) {
                if (s.length() > best.length() || (s.length() == best.length() && s.compareTo(best) < 0)) {
                    best = s;
                }
            }
        }

        System.out.println(best.isEmpty() ? "0" : best);
    }

    static boolean canPlaceNonOverlapping(List<int[]> positions, int len) {
        boolean[][] used = new boolean[n][m];
        for (int[] pos : positions) {
            int r = pos[0];
            int c = pos[1];
            int d = pos[2];
            int L = pos[3];
            if (L != len) continue;
            // Check if this placement overlaps
            boolean ok = true;
            int rr = r, cc = c;
            for (int k = 0; k < len; k++) {
                int wr = ((rr % n) + n) % n;
                int wc = ((cc % m) + m) % m;
                if (used[wr][wc]) {
                    ok = false;
                    break;
                }
                rr += dr[d];
                cc += dc[d];
            }
            if (ok) {
                rr = r; cc = c;
                for (int k = 0; k < len; k++) {
                    int wr = ((rr % n) + n) % n;
                    int wc = ((cc % m) + m) % m;
                    used[wr][wc] = true;
                    rr += dr[d];
                    cc += dc[d];
                }
                return true;
            }
        }
        return false;
    }
}

