import java.io.*;
import java.util.*;

/*
We need the longest repeated string on a toroidal grid ("donut-shaped"),
readable in any of 8 directions. Two occurrences may reuse cells across
different candidates, but for the chosen repeated string there must exist
two non-overlapping occurrences (their cell sets are disjoint).

If multiple longest strings exist, output lexicographically smallest.
If none, output 0.

Assumed input format:
R C
R lines of length C

This is the standard interpretation for such grid problems.

Approach:
- Enumerate every line induced by each start cell and each of 8 directions.
  Because the board is toroidal, each such walk is periodic. Its cycle length is:
      lcm(R / gcd(R,dr), C / gcd(C,dc))
  (with dr,dc in {-1,0,1}, not both zero)
- For each line, build its cyclic string of that length and duplicate it
  so every substring up to full cycle length can be read linearly.
- Insert all substrings into a trie. For each trie node (substring), store up to
  two occurrence masks represented as BitSet over R*C cells, but only if they are
  pairwise disjoint. This is enough to determine existence of two non-overlapping
  occurrences.
- DFS trie preferring deeper nodes; among equal depths choose lexicographically
  smallest by traversing children in character order.

This is practical for moderate board sizes common in contest tasks.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static class Node {
        TreeMap<Character, Integer> next = new TreeMap<>();
        BitSet occ1, occ2; // store up to two disjoint occurrences
        boolean valid;     // true if two disjoint occurrences exist
    }

    static int R, C, N;
    static char[][] grid;
    static ArrayList<Node> trie = new ArrayList<>();

    static int[] DR = {-1,-1,-1,0,0,1,1,1};
    static int[] DC = {-1,0,1,-1,1,-1,0,1};

    static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    static int cycleLength(int dr, int dc) {
        long a = (dr == 0) ? 1 : (R / gcd(R, Math.abs(dr)));
        long b = (dc == 0) ? 1 : (C / gcd(C, Math.abs(dc)));
        long g = gcd(a, b);
        return (int)(a / g * b);
    }

    static int id(int r, int c) {
        return r * C + c;
    }

    static boolean disjoint(BitSet a, BitSet b) {
        BitSet t = (BitSet) a.clone();
        t.and(b);
        return t.isEmpty();
    }

    static void registerOccurrence(int nodeIdx, BitSet occ) {
        Node node = trie.get(nodeIdx);
        if (node.valid) return;

        if (node.occ1 == null) {
            node.occ1 = occ;
            return;
        }
        if (disjoint(node.occ1, occ)) {
            node.occ2 = occ;
            node.valid = true;
            return;
        }
        if (node.occ2 == null) {
            node.occ2 = occ;
            return;
        }
        if (disjoint(node.occ2, occ)) {
            node.valid = true;
        }
    }

    static int getChild(int nodeIdx, char ch) {
        Node node = trie.get(nodeIdx);
        Integer nx = node.next.get(ch);
        if (nx != null) return nx;
        int idx = trie.size();
        trie.add(new Node());
        node.next.put(ch, idx);
        return idx;
    }

    static void buildTrie() {
        trie.add(new Node()); // root

        for (int r0 = 0; r0 < R; r0++) {
            for (int c0 = 0; c0 < C; c0++) {
                for (int d = 0; d < 8; d++) {
                    int dr = DR[d], dc = DC[d];
                    int L = cycleLength(dr, dc);

                    char[] line = new char[2 * L];
                    int[] cells = new int[2 * L];

                    int r = r0, c = c0;
                    for (int i = 0; i < L; i++) {
                        line[i] = grid[r][c];
                        cells[i] = id(r, c);
                        r = (r + dr + R) % R;
                        c = (c + dc + C) % C;
                    }
                    for (int i = 0; i < L; i++) {
                        line[L + i] = line[i];
                        cells[L + i] = cells[i];
                    }

                    for (int s = 0; s < L; s++) {
                        int node = 0;
                        BitSet bs = new BitSet(N);
                        for (int len = 1; len <= L; len++) {
                            int pos = s + len - 1;
                            bs.set(cells[pos]);
                            node = getChild(node, line[pos]);
                            registerOccurrence(node, (BitSet) bs.clone());
                        }
                    }
                }
            }
        }
    }

    static String best = "";

    static void dfs(int nodeIdx, StringBuilder path) {
        Node node = trie.get(nodeIdx);
        if (node.valid) {
            String cur = path.toString();
            if (cur.length() > best.length() ||
                (cur.length() == best.length() && cur.compareTo(best) < 0)) {
                best = cur;
            }
        }
        for (Map.Entry<Character, Integer> e : node.next.entrySet()) {
            path.append(e.getKey());
            dfs(e.getValue(), path);
            path.deleteCharAt(path.length() - 1);
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        String first = fs.next();
        if (first == null) return;
        R = Integer.parseInt(first);
        C = fs.nextInt();
        grid = new char[R][];
        for (int i = 0; i < R; i++) {
            grid[i] = fs.next().toCharArray();
        }
        N = R * C;

        buildTrie();
        dfs(0, new StringBuilder());

        System.out.println(best.isEmpty() ? "0" : best);
    }
}
